export default function r(e){const a=[...e.children];if(a.length<5)return;const c=document.createElement("div");c.className="las-intro-copy",a.slice(0,3).forEach(n=>c.append(n));const t=document.createElement("div");t.className="las-intro-card",a.slice(3).forEach(n=>t.append(n)),e.append(c,t),e.classList.add("las-intro-ready")}
